changeSet.sql:
update anlassconfig set sehennahvisus = 'REQUIRED' where anlasstyp = 'KINDERGARTEN';
update anlassconfig set seheninspektion = 'NOT_VISIBLE' where anlasstyp in ('KLASSE_4', 'KLASSE_8', 'KLASSE_9', 'FREMDSPRACHEN');
update anlassconfig set sehenkonvergenz = 'NOT_VISIBLE' where anlasstyp in ('KLASSE_4', 'KLASSE_8', 'KLASSE_9', 'FREMDSPRACHEN');
update anlassconfig set sehenbemerkungen = 'OPTIONAL' where anlasstyp not in ('IMPFAKTION', 'IMPFSPRECHSTUNDE', 'IMPFTERMIN');
